-- ========================================================================

-- Safety-critical flags for a urinalysis result, independent of the axes.

CREATE TABLE urinalysis_test_result_grade_flag (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ DEFAULT NULL,

    urinalysis_test_result_grade_id UUID NOT NULL
        REFERENCES urinalysis_test_result_grade(id) ON DELETE CASCADE,
    flag_id VARCHAR(50) NOT NULL,
    category VARCHAR(40) NOT NULL DEFAULT ''
        CHECK (category IN (
            'critical-result-alert',
            'incidental-finding',
            'discrepancy-with-request',
            'abnormal-requiring-action',
            'urgent-referral',
            'inadequate-technique',
            'unexpected-finding',
            'missing-impression',
            'missing-measurement',
            'other',
            ''
        )),
    priority VARCHAR(10) NOT NULL DEFAULT ''
        CHECK (priority IN ('low', 'medium', 'high', '')),
    description VARCHAR(500) NOT NULL DEFAULT '',
    suggested_action VARCHAR(500) NOT NULL DEFAULT ''
);

CREATE INDEX index_urinalysis_test_result_grade_flag_grade_id
    ON urinalysis_test_result_grade_flag(urinalysis_test_result_grade_id);

CREATE TRIGGER trigger_urinalysis_test_result_grade_flag_updated_at
    BEFORE UPDATE ON urinalysis_test_result_grade_flag
    FOR EACH ROW
    EXECUTE FUNCTION set_updated_at();

COMMENT ON TABLE urinalysis_test_result_grade_flag IS
    'Safety-critical flags that fire independently of the four axes, with priority and a suggested action for the reporting / requesting team.';
